[SPECIALIST_FINDING]
{
  "specialty": "kdoctor-ophthalmology",
  "answer": "62세 여성의 점진적 변시증 + 드루젠은 연령관련황반변성(AMD)이 가장 개연성이 높으나, 중심장액망막병증(CSCR)과 황반부 망막하 유리막은 드루젠 없이도 변시증을 유발하므로 SD-OCT로 감별이 필요합니다. 드루젠이 관찰된다는 점만으로 nAMD 전환을 시사하지 않으며, 전환은 망막하액·망막내액·망막하 출혈·유리막 사절·신생혈관 등 SD-OCT/OCT-A 소견으로 판단합니다. 다만 드루젠을 동반한 CSCR(특히 스테로이드 노출력)은 감별에서 빼지 말아야 하고, 기저 병력·약물 미상이라 가설별 확률은 information 낮음입니다.",

  "red_flag": {
    "present": false,
    "items": [
      {
        "id": "OP1/OP2",
        "evidence": "점진적 중심 시야 왜곡으로 서술됨. 급격한 시력 소실·커튼 가림·날파리 급증은 질문에 명시되지 않음(확인되지 않음).",
        "basis": "history"
      }
    ]
  },

  "hypotheses": [
    {
      "name": "연령관련황반변성(AMD), 중간단계 이상 — 건성 우세 가능",
      "icd10": "H35.31",
      "must_not_miss": false,
      "probability_band": "high",
      "supports": [
        { "text": "62세(고령) + 점진적 변시증", "basis": "history" },
        { "text": "안저에서 드루젠 관찰 — AMD의 정의적 소견", "basis": "image" }
      ],
      "against": [
        { "text": "변시증의 정도·기간·단안/양안 여부, 시력 수치 미상", "basis": "history" },
        { "text": "드루젠 크기·개수·색(연성/경성), 색소 변화, 지도모양위축 여부 미상(SD-OCT·안저 상세 필요)", "basis": "image" }
      ]
    },
    {
      "name": "황반 신생혈관(nAMD) — 드루젠 배경 위 전환 의심",
      "icd10": "H35.32",
      "must_not_miss": true,
      "probability_band": "medium",
      "supports": [
        { "text": "드루젠 존재 자체는 nAMD 위험 배경이나 확정 근거 아님(확인되지 않음)", "basis": "image" },
        { "text": "변시증은 망막하액·출혈 시에도 나타남 — 감별 위해 SD-OCT 필수", "basis": "guideline" }
      ],
      "against": [
        { "text": "망막하액·출혈·유리막 사절·신생혈관 소견이 질문에 없음(확인되지 않음)", "basis": "image" },
        { "text": "시력 저하의 급격성 여부 미상 — nAMD는 급격한 변시증/시력 저하가 흔함", "basis": "history" }
      ]
    },
    {
      "name": "중심장액망막병증(CSCR)",
      "icd10": "H35.71",
      "must_not_miss": false,
      "probability_band": "medium",
      "supports": [
        { "text": "중심 시야 변시증 + 40~60대, 여성에서 발생 가능", "basis": "history" },
        { "text": "드루젠 동반 CSCR도 존재하므로 드루젠만으로 CSCR 배제 불가", "basis": "guideline" }
