      ],
      "against": [
        { "text": "유리막 사절은 SD-OCT에서 확인하는 소견으로 질문에 없음(확인되지 않음)", "basis": "image" },
        { "text": "SDD는 AMD 진행·nAMD 위험과 관련되나 단독 확정 진단 불가", "basis": "guideline" }
      ]
    },
    {
      "name": "당뇨황반부종 / 고혈압망막병증 등 전신질환 관련 황반병변",
      "icd10": "H35.81 / H35.03",
      "must_not_miss": true,
      "probability_band": "low",
      "supports": [
        { "text": "전신질환 병력 미상 — 배제 불가", "basis": "history" }
      ],
      "against": [
        { "text": "당뇨·고혈압 병력 미상(확인되지 않음)", "basis": "history" },
        { "text": "안저 소견 상세 미상(출혈·미세혈관류 등)", "basis": "image" }
      ]
    }
  ],

  "missing_info": [
    "가장 판별력이 큰 한 가지: 증상의 발현 시점과 진행 속도 — '며칠~수 주 이내 급격한 악화인지, 수 개월에 걸친 서서히 진행인지?' (nAMD vs CSCR vs 건성 AMD 감별에 가장 결정적)"
  ],

  "suggested_tests": [
    { "name": "SD-OCT(스펙트럼영역 빛간섭단층촬영)", "purpose": "망막하액·망막내액·RPE 박리·드루젠 종류(SDD 여부)·유리막 사절 확인 및 감별", "urgency": "24h", "basis": "guideline" },
    { "name": "OCT-A", "purpose": "맥락막 신생혈관(2형·1형) 또는 폴립상 맥락막혈관병증(PCV) 평가, 드루젠·SDD 분포 확인", "urgency": "24h", "basis": "guideline" },
    { "name": "형광안저촬영(FFA)", "purpose": "누출 양상(다발성, 조기 과형광·후기 누출 = CSCR / 결절성 과형광·경계 불명확 = nAMD), 감별 진단", "urgency": "routine", "basis": "guideline" },
    { "name": "인도시아닌 그린 혈관조영(ICGA)", "purpose": "PCV·결절성 nAMD 의심 시 맥락막 신생혈관 평가(선택)", "urgency": "routine", "basis": "guideline" },
    { "name": "안저검사(광각·세극등), 시력·굴절검사, Amsler 자가검사", "purpose": "기본 평가 및 자가 모니터링", "urgency": "24h", "basis": "guideline" },
    { "name": "기저 병력·복용 약물 확인(스테로이드 점안/경구/주사, 당뇨·고혈압 병력)", "purpose": "CSCR·당뇨망막병증·고혈압망막병증 배제", "urgency": "routine", "basis": "history" }
  ],

  "suggested_treatments": [
    { "kind": "referral", "description": "안과 대면 진료 의뢰. SD-OCT/OCT-A/FFA로 nAMD 여부 판정 후 항VEGF 치료 여부 결정. 응급 신호(급격한 시력 저하·중심 암점·출혈) 발생 시 즉시 응급실.", "basis": "guideline" },
    { "kind": "self_care", "description": "Amsler 자가검사로 변시증 변화 모니터링, 눈 비비지 않기, 무처방 스테로이드 안약 사용 금지(감염 악화·CSCR 악화 위험).", "basis": "guideline" }
  ],

  "handoff": { "better_specialty": "", "reason": "" },

